function b64u(bytes: Uint8Array): string { let s = ""; bytes.forEach((b) => (s += String.fromCharCode(b))); return btoa(s).replaceAll("+", "-").replaceAll("/", "_").replaceAll("=", ""); }
function unb64u(s: string): Uint8Array { const b = s.replaceAll("-", "+").replaceAll("_", "/"); const bin = atob(b + "=".repeat((4 - (b.length % 4)) % 4)); const out = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i); return out; }
async function hmac(secret: string, msg: string) { const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]); return new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(msg))); }
export async function issueCert(secret: string, p: object) { const body = b64u(new TextEncoder().encode(JSON.stringify(p))); return `${body}.${b64u(await hmac(secret, body))}`; }
export async function verifyCert(secret: string, cert: string) { const [body, sig] = cert.split("."); if (!body || !sig) return null; if (b64u(await hmac(secret, body)) !== sig) return null; try { return JSON.parse(new TextDecoder().decode(unb64u(body))); } catch { return null; } }
