function b64u(bytes: Uint8Array): string { let s = ""; bytes.forEach((b) => (s += String.fromCharCode(b))); return btoa(s).replaceAll("+", "-").replaceAll("/", "_").replaceAll("=", ""); }
function unb64u(s: string): Uint8Array { const b = s.replaceAll("-", "+").replaceAll("_", "/"); const bin = atob(b + "=".repeat((4 - (b.length % 4)) % 4)); const out = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i); return out; }
async function hmac(secret: string, msg: string): Promise<Uint8Array> { const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]); return new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(msg))); }
export async function signChallenge(secret: string, p: { id: string; gate: string; params?: Record<string, unknown>; iat: number; exp: number }): Promise<string> { const body = b64u(new TextEncoder().encode(JSON.stringify(p))); const sig = b64u(await hmac(secret, body)); return `${body}.${sig}`; }
export async function verifyChallenge(secret: string, token: string) { const [body, sig] = token.split("."); if (!body || !sig) return null; const expect = b64u(await hmac(secret, body)); if (expect !== sig) return null; try { const p = JSON.parse(new TextDecoder().decode(unb64u(body))); if (Date.now() / 1000 > p.exp) return null; return p; } catch { return null; } }
